from lib import *
FV="Portions de fruits et légumes"
def fv(n): return (FV,f"Portions de fruits et légumes par portion : {n}")
FZ="Instructions de congélation : "
recs=[
R(7014881,"Poulet jerk et salsa d'ananas grillé",
"Un plat jamaïcain classique, populaire dans toutes les Caraïbes. Le « jerk » désigne l'assaisonnement épicé dans lequel le poulet est mariné. Peut être cuit au four ou au barbecue.",
"4","385 g",
["8 petits hauts de cuisse de poulet désossés (720 g)","3 baies de piment de la Jamaïque","1 cuillère à café de muscade moulue","1 cuillère à café de cannelle moulue","1 petit oignon rouge, finement râpé","4 oignons verts, parés et finement hachés","1 piment rouge, épépiné et finement haché","1 lime, finement râpée (zeste) et pressée (jus)",("Pour la salsa d'ananas","1 ananas frais de taille moyenne, pelé, ou 8 rondelles d'ananas en conserve"),("Pour la salsa d'ananas","1 vaporisation d'huile en aérosol à 1 calorie"),("Pour la salsa d'ananas","1 piment vert, épépiné et finement haché"),("Pour la salsa d'ananas","1 lime, jus seulement"),("Pour la salsa d'ananas","1/2 petit oignon rouge, finement haché"),("Pour la salsa d'ananas","1 petite poignée de coriandre fraîche, finement hachée"),("Pour la salade de carottes et de pommes","2 carottes, pelées et grossièrement râpées"),("Pour la salade de carottes et de pommes","1 pomme Granny Smith, épépinée et grossièrement râpée"),("Pour la salade de carottes et de pommes","2 cuillères à café de vinaigre de cidre de pomme"),("Pour la salade de carottes et de pommes","1 cuillère à soupe de graines de tournesol")],
["À l'aide d'un couteau bien aiguisé, entaillez la chair du poulet à quelques endroits et placez-le dans un plat non métallique. Faites griller à sec les baies de piment de la Jamaïque 2 à 3 minutes, jusqu'à ce qu'elles dégagent leur parfum, puis versez-les dans un mortier et pilez-les en poudre. Ajoutez le reste des ingrédients du jerk et pilez pour obtenir une pâte épaisse. Mélangez au poulet pour bien l'enrober. Couvrez et laissez mariner toute la nuit si vous avez le temps, ou au moins 1 heure.","Pendant ce temps, retirez et jetez le cœur de l'ananas et tranchez la chair. Faites chauffer une poêle à griller jusqu'à ce qu'elle fume. Vaporisez l'ananas d'huile en aérosol faible en calories et faites-le griller 2 minutes de chaque côté, jusqu'à ce qu'il soit joliment marqué de lignes grillées.","Préchauffez le gril à température élevée. Placez le poulet sur une grille de gril au-dessus d'une plaque de cuisson et faites-le griller 20 à 25 minutes, en le retournant de temps en temps, jusqu'à ce qu'il soit bien cuit (vérifiez avec un thermomètre à viande ou en enfonçant une brochette en métal dans la partie la plus épaisse du poulet : si le jus est clair, il est cuit. Sinon, remettez-le sous le gril 4 à 5 minutes, puis vérifiez à nouveau).","Pendant la cuisson du poulet, mélangez les carottes, les pommes et le vinaigre de cidre. Assaisonnez de poivre noir fraîchement moulu et saupoudrez de graines. Servez avec le poulet et la salsa. Parsemez le poulet d'un peu de coriandre et de piment rouge supplémentaires si vous le souhaitez."],
["Cette recette est riche en protéines et en vitamine C, et constitue une source de fer.",fv(2)]),
R(7017274,"Filet d'agneau et couscous à la menthe",
"Cette recette alléchante à la menthe fraîche hachée est un plat idéal pour recevoir.",
"4","350 g",
["450 g de filet d'agneau maigre","poivre noir fraîchement moulu","2 cuillères à soupe de gelée de groseille","400 ml de bouillon de légumes (utilisez un bouillon de légumes sans gluten pour que cette recette soit sans gluten)","2 cuillères à café de coriandre moulue","2 cuillères à café de cumin moulu","175 g de couscous (utilisez du quinoa pour que cette recette soit sans gluten)","1 cuillère à soupe de menthe fraîche hachée","4 tomates, hachées","2 cuillères à soupe de persil haché","le jus et le zeste de 1 citron"],
["Placez l'agneau sur une plaque de cuisson et assaisonnez de poivre noir.","Faites chauffer la gelée de groseille et versez-la sur l'agneau. Utilisez un pinceau de cuisine pour l'étaler sur toute la surface.","Faites cuire l'agneau sous un gril chaud 10 à 15 minutes. Retirez-le du gril, couvrez-le de papier d'aluminium et laissez-le reposer 5 minutes.","Pendant ce temps, portez le bouillon de légumes à ébullition et ajoutez les épices. Ajoutez le couscous, retirez du feu et couvrez avec un couvercle. Laissez gonfler à la vapeur 1 minute, puis égrenez les grains à la fourchette.","Incorporez la menthe hachée, les tomates, le persil, le jus et le zeste de citron, et répartissez dans les assiettes de service.","Tranchez l'agneau en fines tranches et disposez-les sur le couscous."],
["Vous pouvez aussi utiliser de la poitrine de poulet ou du filet de porc avec cette recette.",FZ+"congelez le couscous et l'agneau séparément. Décongelez au réfrigérateur ou au micro-ondes et réchauffez jusqu'à ce que ce soit bien chaud à cœur.",fv(1)]),
R(7019856,"Soupe mulligatawny",
"Parfaite pour les soirées froides, cette soupe épicée et réconfortante est remplie de légumes, de lentilles et de riz.",
"8","266 g",
["2 cuillères à café d'huile de tournesol","1 gros oignon, finement haché","1 carotte, coupée en dés","1 patate douce, coupée en dés (250 g)","1 boîte de 400 g de tomates","75 g de lentilles rouges","2 gousses d'ail, écrasées","1 cube de bouillon de légumes","1 cuillère à soupe de pâte de cari moyen (ou de poudre)","1 litre d'eau bouillante","75 g de riz basmati cuit dans 1 litre d'eau bouillante","coriandre fraîche, pour servir"],
["Mettez l'huile dans une grande casserole avec l'oignon. Faites cuire 5 minutes en remuant régulièrement, jusqu'à ce qu'il commence à dorer.","Ajoutez la carotte et la patate douce, et faites cuire encore 5 minutes en remuant régulièrement.","Ajoutez maintenant les tomates, les lentilles, l'ail, le cube de bouillon, la pâte de cari et 1 litre d'eau bouillante. Portez à ébullition, réduisez le feu, couvrez et laissez mijoter 15 minutes.","Pendant ce temps, faites bouillir le riz 10 minutes, rincez-le dans une passoire sous l'eau froide et réservez.","Réduisez les légumes en purée lisse à l'aide d'un mélangeur à main ou d'un robot culinaire.","Incorporez le riz à la soupe et servez avec un peu de coriandre fraîchement hachée."],
["Ajoutez une poitrine de poulet coupée en petits dés en même temps que les tomates et utilisez un cube de bouillon de poulet.","Cette recette est riche en vitamine A, qui aide votre système immunitaire à bien fonctionner.",FZ+"peut être congelé une fois cuit. Congelez en portions, puis décongelez au réfrigérateur, ou au micro-ondes en remuant régulièrement.",fv(1)]),
R(7023571,"Rarebit gallois aux poireaux",
"Une version simple et plus saine du fromage sur toast. Parfait pour le petit-déjeuner ou le brunch.",
"2","164 g",
["1 cuillère à café d'huile de colza","1 gros poireau, finement haché","2 tranches de pain de seigle complet","1 œuf moyen","1 cuillère à café bombée de moutarde de Dijon","30 g de cheddar vieilli, finement râpé"],
["Mettez l'huile dans une poêle, puis ajoutez le poireau haché et faites cuire à feu doux à moyen en remuant fréquemment, 4 minutes, jusqu'à ce qu'il soit tendre.","Retirez le poireau du feu et laissez-le refroidir quelques minutes.","Pendant ce temps, allumez le gril à température élevée et faites griller un côté du pain de seigle.","Mettez l'œuf dans un bol avec la moutarde et battez légèrement. Incorporez ensuite la moitié du fromage râpé et tout le poireau.","Étalez le mélange uniformément sur le côté non grillé du pain, saupoudrez du reste du fromage et faites gratiner environ 2 à 3 minutes, jusqu'à ce que ce soit doré."],
["L'utilisation d'un cheddar vieilli permet d'en mettre moins tout en obtenant une saveur prononcée.","Le pain de seigle est une excellente céréale complète : il est riche en fibres et vous rassasiera plus longtemps, ce qui le rend idéal pour le petit-déjeuner.",fv(1)]),
R(7025833,"Sandwich ouvert aux sardines et au piment",
"Un déjeuner savoureux et consistant que vous pouvez préparer en moins de 5 minutes.",
"1","190 g",
["1/2 petit piment rouge (10 g)","2 petites tranches de pain de blé entier (40 g)","1 boîte de 120 g de sardines à l'huile d'olive","roquette (40 g)"],
["Épépinez et tranchez finement 1/2 petit piment rouge.","Égouttez une boîte de sardines en réservant un peu de l'huile.","Mettez une poignée de roquette sur les tranches de pain et disposez les sardines par-dessus.","Parsemez de tranches de piment et arrosez d'un peu de l'huile réservée."],
[fv(0)]),
R(7026697,"Mini tartelettes au saumon fumé et à la ciboulette",
"Des bouchées de fruits de mer alléchantes, idéales à servir avec des boissons.",
"36","18 g",
["350 g de pâte brisée prête à l'emploi","1 œuf, battu","150 ml de crème fraîche légère","2 cuillères à soupe de ciboulette, hachée","75 g de saumon fumé, grossièrement haché","poivre noir fraîchement moulu"],
["Préchauffez le four à 200 ºC/thermostat 6.","Abaissez finement la pâte. Découpez environ 36 ronds de 5 cm avec un emporte-pièce et utilisez-les pour garnir de mini moules à tartelettes. Faites cuire à blanc 10 minutes.","Battez ensemble l'œuf et la crème fraîche, assaisonnez bien, puis incorporez la ciboulette et le saumon.","Déposez un peu du mélange dans chaque fond de pâte et faites cuire environ 10 minutes, jusqu'à ce que ce soit doré et pris.","Laissez refroidir un peu et servez."],
["Vous pouvez utiliser du jambon fumé à la place du saumon.","Pour une version végétarienne, remplacez le saumon fumé par des tomates séchées tranchées.",fv(0)]),
R(7032450,"Moussaka aux légumes",
"Un plat consistant mais plus faible en gras, rempli de légumes et plus riche en fibres, garni de yogourt épicé au fromage.",
"6","245 g",
["1 patate douce (environ 350 g), pelée et coupée en tranches de 0.5 cm d'épaisseur","1 aubergine, finement tranchée","1 cuillère à café d'huile de colza","2 oignons moyens, finement hachés","3 gousses d'ail, hachées","1 poivron rouge, finement haché","1 poivron jaune, finement haché","1 courgette, coupée en petits dés","1 carotte, râpée","1 boîte de 400 g de lentilles, égouttées","1 boîte de 400 g de tomates","1 cuillère à café d'origan","1 cuillère à café de thym",("Pour la garniture","200 g de yogourt grec à 0 % de matières grasses"),("Pour la garniture","50 g de cheddar à teneur réduite en gras, finement râpé"),("Pour la garniture","1 cuillère à café bombée de cannelle moulue")],
["Préchauffez le four à 180 °C/thermostat 4. Faites bouillir les tranches de patate douce 7 à 10 minutes, jusqu'à ce qu'elles soient juste tendres. Égouttez et réservez.","Faites griller les tranches d'aubergine 4 minutes de chaque côté et réservez.","Mettez l'huile dans une casserole et ajoutez les oignons. Lorsqu'ils commencent à dorer, ajoutez les poivrons, les courgettes et les carottes. Faites cuire 5 minutes.","Ajoutez l'ail, les lentilles, les tomates, l'origan et le thym. Portez à ébullition, réduisez le feu, couvrez et laissez mijoter 5 minutes.","Pendant ce temps, pour préparer la garniture, mélangez le yogourt, le cheddar et la cannelle.","Dans un plat allant au four, déposez une couche d'aubergine, ajoutez une cuillerée du mélange de lentilles et de tomates, puis une couche de patate douce. Couvrez d'une autre portion du mélange de lentilles et de tomates et superposez en alternance, en terminant par l'aubergine.","Étalez le mélange de yogourt sur le dessus à la cuillère et faites cuire au four 15 minutes."],
["Vous pouvez préparer des moussakas individuelles dans des plats allant au four pour les servir directement à table.","Pour une saveur optimale, laissez reposer 5 à 10 minutes avant de servir.",FZ+"peut être congelé une fois cuit. Décongelez au réfrigérateur ou au micro-ondes et réchauffez à fond jusqu'à ce que ce soit bien chaud à cœur.",fv(3)]),
R(7034454,"Mini puddings de Noël",
"Version plus saine, en bouchées, du traditionnel pudding de Noël. Sans sucre ajouté, avec de la farine d'avoine, de la banane écrasée et de la pomme à la place du suif traditionnel (graisse animale).",
"24","35 g",
["350 g de fruits secs mélangés","3 figues séchées, hachées","1 cuillère à café d'épices mélangées","1 cuillère à café de cannelle moulue","1 cuillère à café de gingembre moulu","1 pincée de clou de girofle moulu","250 ml d'eau bouillante","1 grosse banane (150 g)","1 pomme non pelée, râpée","75 g de farine d'avoine fine","60 g d'amandes moulues","25 g de graines de tournesol","le zeste râpé de 1 orange","2 cuillères à café d'huile de tournesol, pour huiler"],
["Préchauffez le four à 170 °C/thermostat 3. Mettez les fruits secs, les figues et les épices dans un bol. Mélangez, puis ajoutez l'eau bouillante, couvrez et laissez reposer 15 minutes.","Pendant ce temps, écrasez la banane et incorporez la pomme râpée, la farine d'avoine, les amandes moulues, les graines et le zeste.","Ensuite, réunissez le tout dans un seul bol en mélangeant bien.","Huilez légèrement deux moules à mini petits pains de 12 cavités (ou faites simplement 2 fournées dans le même moule) et répartissez-y le mélange.","Faites cuire au four 15 à 25 minutes, selon la taille des moules.","Lorsqu'ils sont cuits (ils sont fermes et la lame d'un couteau en ressort propre), démoulez-les sur une grille et laissez refroidir."],
["Vous pouvez utiliser un moule de n'importe quelle taille, il suffit d'ajuster le temps de cuisson en conséquence, car les plus gros pains mettront plus de temps à cuire.","Ces petits puddings cuisent beaucoup plus vite et vous n'avez pas besoin de les cuire à la vapeur, ce qui les rend aussi idéaux pour les fêtes d'avant Noël.","Essayez de les garnir de noix ou de tranches d'orange pour des puddings ultra luxueux.",FZ+"décongelez au micro-ondes, puis faites cuire à la vapeur, au micro-ondes ou dans un four modéré.",fv(0)]),
R(7034894,"Quartiers de pommes de terre épicés",
"Idéal pour recevoir et délicieusement sain, avec beaucoup moins de gras que les versions du commerce. Remarque : les trempettes ne sont pas incluses dans l'analyse.",
"8","317 g",
["8 pommes de terre à cuire au four, chacune coupée en 8 quartiers (poids total 1.6 kg)","3 cuillères à soupe d'huile de colza","1 cuillère à soupe de paprika",("Pour la trempette à l'ail et aux fines herbes","1 pot de 200 g de fromage à la crème à teneur réduite en gras"),("Pour la trempette à l'ail et aux fines herbes","1 pot de 200 g de fromage frais sans gras"),("Pour la trempette à l'ail et aux fines herbes","2 gousses d'ail, écrasées"),("Pour la trempette à l'ail et aux fines herbes","3 cuillères à soupe de menthe fraîche, hachée"),("Pour la trempette à l'ail et aux fines herbes","3 cuillères à soupe de persil frais, haché"),("Pour la salsa de tomates épicée","1 boîte de 400 g de tomates hachées"),("Pour la salsa de tomates épicée","1 piment rouge"),("Pour la salsa de tomates épicée","1 gousse d'ail, écrasée"),("Pour la salsa de tomates épicée","3 cuillères à soupe de coriandre fraîche, hachée")],
["Préchauffez le four à 200 ºC/thermostat 6.","Placez les quartiers de pommes de terre dans une grande casserole d'eau bouillante et laissez mijoter 5 minutes. Égouttez et déposez dans un grand plat à rôtir.","Mélangez l'huile et le paprika et enrobez-en les quartiers de pommes de terre. Placez sur une plaque de cuisson et faites cuire 20 à 25 minutes, jusqu'à ce qu'ils soient dorés et croustillants.","Pour la trempette à l'ail et aux fines herbes, mélangez simplement tous les ingrédients et versez à la cuillère dans un plat de service.","Égouttez l'excédent de liquide des tomates, puis mixez-les avec le piment, l'ail et la coriandre pendant 30 secondes. Versez à la cuillère dans un plat de service.","Servez les pommes de terre avec les trempettes."],
["Si vous les faites circuler comme bouchées à manger avec les doigts, omettez le paprika sur les pommes de terre, car il tache les doigts !","Vous pouvez utiliser de la poudre de 5 épices chinois à la place du paprika, ou essayer du thym séché.",FZ+"les quartiers peuvent être congelés. Décongelez au micro-ondes et réchauffez au four jusqu'à ce qu'ils soient bien chauds.",fv(0)]),
R(7037421,"Crêpes épaisses de blé entier aux épinards et au cheddar",
"Des crêpes épaisses et fromagées, garnies de tomates et de basilic.",
"4","203 g",
["2 cuillères à café d'huile de tournesol","1 gros oignon, finement haché","1 œuf, battu","150 ml de lait demi-écrémé","100 g de farine de blé entier","200 g d'épinards surgelés, décongelés, excédent d'eau retiré","50 g de cheddar vieilli à teneur réduite en gras, coupé en petits dés","1 bonne pincée de poivre blanc","20 tomates cerises, coupées en quartiers","10 g de basilic frais, haché","1 pincée de poivre noir"],
["Mettez 1 cuillère à café d'huile dans une casserole à feu doux à moyen, puis ajoutez l'oignon. Faites cuire 3 à 4 minutes en remuant régulièrement, jusqu'à ce qu'il soit ramolli, puis retirez du feu.","Battez l'œuf dans le lait, puis mettez la farine dans un bol et incorporez graduellement le mélange de lait en remuant jusqu'à ce que la pâte soit lisse. Ajoutez ensuite les épinards, l'oignon, le fromage et le poivre, puis mélangez.","Faites chauffer une poêle antiadhésive à feu moyen à doux. Ajoutez la cuillère à café d'huile restante et étalez-la dans la poêle avec du papier absorbant, avant d'ajouter 1/4 du mélange. Étalez-le dans la poêle avec le dos d'une cuillère, sur environ 12 à 15 cm de diamètre et 1/2 cm d'épaisseur.","Faites cuire 2 à 3 minutes, puis retournez avec une spatule et faites cuire encore une ou deux minutes de l'autre côté. Servez garni de tomates fraîches, de basilic et de poivre noir."],
["Essayez d'ajouter d'autres légumes aux crêpes, comme de la courgette râpée, des poireaux cuits ou des champignons.","Gardez les crêpes au chaud entre deux assiettes, au-dessus d'une casserole d'eau qui frémit doucement, jusqu'à ce qu'elles soient toutes cuites.",fv(1)]),
R(7040748,"Burgers aux haricots à œil noir, à la feta et aux fines herbes",
"Un délicieux burger sans viande, riche en protéines.",
"6","158 g",
["2 cuillères à café d'huile d'olive","3 oignons verts, finement tranchés","1 boîte de 400 g de haricots à œil noir, égouttés et rincés","75 g de chapelure de pain aux céréales","100 g de feta, émiettée","2 cuillères à soupe de fines herbes fraîches mélangées, hachées","1 œuf, battu","petits pains de blé entier, pour servir (4 x 70 g)","salade, oignons rouges et tomate"],
["Faites chauffer la moitié de l'huile dans une poêle antiadhésive et faites revenir les oignons verts 1 à 2 minutes, jusqu'à ce qu'ils soient ramollis.","Placez les haricots à œil noir dans un grand bol et écrasez-les grossièrement. Incorporez les ingrédients restants et mélangez bien.","Divisez le mélange en 6 et façonnez chaque portion en galette ou en burger.","Placez sur une plaque de cuisson, badigeonnez chaque face du reste de l'huile et réfrigérez au moins 30 minutes, ou jusqu'au moment de les utiliser. Faites cuire 2 à 3 minutes de chaque côté sur un barbecue ou un gril à feu moyen, jusqu'à ce qu'ils soient bien cuits.","Servez dans un petit pain de blé entier garni de salade verte, de tomates et d'oignon rouge."],
["L'analyse nutritionnelle ci-dessus inclut un petit pain de blé entier comme suggestion de service.","Vous pouvez utiliser d'autres haricots, comme des haricots rouges, des cannellini ou des haricots mélangés.","Ajoutez de l'ail écrasé et des flocons de piment pour plus de saveur.","Réduisez les glucides en savourant ce burger végétarien sans le pain.",FZ+"congelez en portions emballées individuellement, avec du papier ciré entre chaque burger. Décongelez complètement et réchauffez jusqu'à ce que ce soit bien chaud à cœur.",fv(0)]),
R(7041630,"Soupe de courge butternut rôtie et de lentilles rouges",
"Une soupe chaude et consistante, facile à préparer, faible en gras, riche en fibres et très rassasiante.",
"4","414 g",
["1 courge butternut (environ 700 g à 1 kg)","2 cuillères à café d'huile de tournesol","1 gros oignon, grossièrement haché","1 carotte, grossièrement hachée","1 litre de bouillon de légumes réduit en sel (préparé avec un cube)","120 g de lentilles rouges décortiquées","poivre blanc, au goût","4 cuillères à soupe de crème fraîche à teneur réduite en gras","ciboulette fraîche, hachée"],
["Préchauffez le four à 200 °C/thermostat 7. Coupez la courge butternut en quartiers dans le sens de la longueur, retirez les graines, badigeonnez d'un peu d'huile et faites cuire au four 25 minutes.","Pendant ce temps, mettez l'oignon et la carotte dans la casserole avec 1 cuillère à café d'huile et faites cuire doucement quelques minutes, jusqu'à ce que l'oignon commence à dorer.","Versez maintenant le bouillon dans la casserole, ajoutez les lentilles, mélangez et laissez mijoter environ 15 minutes.","Sortez la courge butternut du four, retirez la chair avec une cuillère et ajoutez-la à la soupe.","Laissez mijoter encore 5 minutes, ajoutez une bonne pincée de poivre, puis mixez au mélangeur à main ou au robot culinaire jusqu'à ce que ce soit lisse.","Servez avec un tourbillon de crème fraîche à teneur réduite en gras et quelques brins de ciboulette hachée."],
["Cette recette est riche en vitamine A, qui aide votre système immunitaire à fonctionner de façon optimale.","Les cubes de bouillon contiennent du sel, alors n'ajoutez pas de sel supplémentaire pendant la cuisson. Lorsque vous faites mijoter la soupe, vous réduisez la teneur en eau et concentrez la teneur en sel : goûtez donc une fois la soupe cuite et ajoutez du sel seulement si nécessaire.",FZ+"congelez en portions, puis décongelez au réfrigérateur, ou au micro-ondes, et réchauffez à fond jusqu'à ce que ce soit bien chaud.",fv(3)]),
R(7044698,"Soupe aux lentilles rouges",
"Une soupe savoureuse, à la fois réconfortante et nutritive.",
"2","304 g",
["100 g de lentilles rouges, rincées","1 petit oignon, haché","1 carotte, hachée","1 gousse d'ail, écrasée","600 ml de bouillon de légumes faible en sel","2 cuillères à soupe de crème fraîche légère","1 cuillère à soupe de persil frais, haché","poivre noir fraîchement moulu","pain, pour servir"],
["Mettez les lentilles, l'oignon, la carotte, l'ail et le bouillon dans une casserole, portez à ébullition et laissez mijoter 20 à 25 minutes, jusqu'à ce que les lentilles soient tendres.","Transférez dans un mélangeur avec la crème fraîche et le persil et mixez jusqu'à ce que ce soit lisse. Assaisonnez et servez avec un morceau de pain."],
["Pour une version végétalienne, omettez simplement la crème fraîche ou ajoutez plutôt 4 cuillères à soupe de lait de soja.","Relevez-la avec 1 cuillère à café de pâte ou de poudre de cari, ou une pincée de flocons de piment.",FZ+"congelez en portions, puis décongelez au réfrigérateur, ou au micro-ondes, en prenant soin de remuer régulièrement.",fv(2)]),
R(7046638,"Tasse au micro-ondes : gruau de fruits aux pommes et à la cannelle",
"Ce gruau de fruits est réconfortant, rassasiant et rapide à préparer, idéal pour bien commencer la journée.",
"1","263 g",
["35 g de flocons d'avoine","1 cuillère à café d'édulcorant artificiel (facultatif)","1 cuillère à café de cannelle, plus une pincée pour garnir","1 petite pomme, coupée en petits morceaux","25 ml de lait demi-écrémé"],
["Mettez les flocons d'avoine, l'édulcorant facultatif, la cannelle et la pomme dans une tasse et mélangez.","Ajoutez 100 ml d'eau et faites cuire à puissance maximale (800 W) pendant deux minutes.","Ajoutez le lait, mélangez et saupoudrez d'un peu de cannelle."],
["Vous pouvez utiliser de la poire ou de la banane à la place de la pomme, ou ajouter un peu de fruits secs, comme des pruneaux ou des raisins secs.","Essayez d'ajouter quelques noix hachées, ou des graines de tournesol ou de citrouille.",fv(1)]),
R(7046889,"Chili con carne",
"Ce chili réconfortant est un classique consistant qui plaît toujours. Rempli de légumes et de protéines, c'est un repas rapide et facile à préparer.",
"8","328 g",
["1 cuillère à café d'huile de tournesol","2 oignons, finement hachés","500 g de bœuf haché maigre (5 % de gras)","250 g de champignons, tranchés","1 poivron rouge, finement haché","1 poivron jaune, finement haché","1 courgette, coupée en dés","4 gousses d'ail, écrasées","1 à 2 cuillères à café de piment en poudre (fort ou doux selon votre préférence)","2 cuillères à café d'origan","2 cuillères à café de cumin","1 boîte de 800 g de tomates hachées","1 boîte de 390 g de lentilles (236 g égouttées et rincées)","1 boîte de 400 g de haricots rouges","25 g de chocolat noir (70 % de cacao)"],
["Mettez l'huile dans une grande casserole, puis ajoutez les oignons et faites cuire 3 à 4 minutes, jusqu'à ce qu'ils commencent juste à dorer.","Ajoutez le bœuf haché et faites cuire 5 à 7 minutes (ou jusqu'à ce qu'il soit bien cuit), en défaisant les grumeaux avec une cuillère en bois.","Ajoutez les champignons, les poivrons, la courgette et l'ail. Faites cuire encore 7 à 8 minutes en remuant régulièrement, jusqu'à ce qu'ils ramollissent.","Incorporez le piment, l'origan, le cumin et les tomates, puis couvrez et laissez mijoter doucement 10 minutes, en remuant de temps en temps.","Ajoutez les lentilles et les haricots, et mélangez bien. Couvrez et laissez mijoter encore 5 minutes.","Incorporez le chocolat jusqu'à ce qu'il soit fondu. Servez avec de la salade."],
["Le chocolat noir intensifie les saveurs, est plus sain et donne de meilleurs résultats que les autres types de chocolat.",FZ+"peut être congelé une fois cuit. Décongelez complètement au réfrigérateur et réchauffez jusqu'à ce que ce soit bien chaud à cœur, en remuant régulièrement.",fv(3)]),
]
